import icontract
from typing import List


def sum_to(a: List[int], n: int) -> int:
    """Sum of the first n elements of a."""
    total = 0
    for i in range(n):
        total += a[i]
    return total


@icontract.require(lambda a: len(a) > 0)
@icontract.ensure(lambda a, result: result == sum_to(a, len(a)))
